/* ── embedded fonts (subset, OFL) ─────────────────────────────────────── */
const JM400 = '';
const JM700 = '';
const IN800 = '';

const FONT_CSS = `
@font-face{font-family:'MxMono';font-style:normal;font-weight:400;font-display:block;src:url(data:font/woff2;base64,${JM400}) format('woff2');}
@font-face{font-family:'MxMono';font-style:normal;font-weight:700;font-display:block;src:url(data:font/woff2;base64,${JM700}) format('woff2');}
@font-face{font-family:'MxSans';font-style:normal;font-weight:800;font-display:block;src:url(data:font/woff2;base64,${IN800}) format('woff2');}
`;

let fontsPromise: Promise<unknown> | null = null;
const ensureFonts = () => {
  if (fontsPromise) return fontsPromise;
  const st = document.createElement('style');
  st.textContent = FONT_CSS;
  document.head.appendChild(st);
  fontsPromise = Promise.all([
    document.fonts.load("400 20px 'MxMono'"),
    document.fonts.load("700 20px 'MxMono'"),
    document.fonts.load("800 60px 'MxSans'"),
  ]).catch(() => null);
  return fontsPromise;
};

const useEmbeddedFonts = () => {
  const [handle] = useState(() => delayRender('fonts'));
  useEffect(() => {
    let done = false;
    const finish = () => {
      if (!done) {
        done = true;
        continueRender(handle);
      }
    };
    const t = setTimeout(finish, 3000);
    ensureFonts().then(finish, finish);
    return () => clearTimeout(t);
  }, [handle]);
};

