const DEG_PER_PX = 360 / MAP.MW;
const MAP_X = -20;
const MAP_Y = 198;

/** lon/lat → frame-space px */
const geo = (lon: number, lat: number): [number, number] => [
  MAP_X + (lon + 180) / DEG_PER_PX,
  MAP_Y + (MAP.LAT_MAX - lat) / DEG_PER_PX,
];

const unpackBits = (b64: string, n: number) => {
  const bin = atob(b64);
  const out = new Uint8Array(n);
  for (let i = 0; i < n; i++) out[i] = (bin.charCodeAt(i >> 3) >> (7 - (i & 7))) & 1;
  return out;
};

/* ── math helpers ─────────────────────────────────────────────────────── */
const clamp01 = (x: number) => (x < 0 ? 0 : x > 1 ? 1 : x);
const smooth = (x: number) => {
  const t = clamp01(x);
  return t * t * (3 - 2 * t);
};
const easeOut = (x: number) => 1 - Math.pow(1 - clamp01(x), 3);
const seg = (x: number, a: number, b: number) => clamp01((x - a) / (b - a));
const pad = (s: string | number, n: number) => String(s).padEnd(n, ' ');
const pad0 = (n: number, w = 2) => String(Math.floor(n)).padStart(w, '0');
const hex = (n: number, w = 2) => n.toString(16).toUpperCase().padStart(w, '0');
const grp = (n: number) => Math.round(n).toLocaleString('en-US');

/* rounded-corner polygon */
const roundPoly = (pts: [number, number][], r: number) => {
  const n = pts.length;
  let d = '';
  for (let i = 0; i < n; i++) {
    const p = pts[(i - 1 + n) % n];
    const c = pts[i];
    const q = pts[(i + 1) % n];
    const v1x = p[0] - c[0], v1y = p[1] - c[1];
    const v2x = q[0] - c[0], v2y = q[1] - c[1];
    const l1 = Math.hypot(v1x, v1y), l2 = Math.hypot(v2x, v2y);
    const t1 = Math.min(r, l1 / 2), t2 = Math.min(r, l2 / 2);
    const a: [number, number] = [c[0] + (v1x / l1) * t1, c[1] + (v1y / l1) * t1];
    const b: [number, number] = [c[0] + (v2x / l2) * t2, c[1] + (v2y / l2) * t2];
    d += i === 0 ? `M${a[0].toFixed(2)} ${a[1].toFixed(2)}` : `L${a[0].toFixed(2)} ${a[1].toFixed(2)}`;
    d += `Q${c[0].toFixed(2)} ${c[1].toFixed(2)} ${b[0].toFixed(2)} ${b[1].toFixed(2)}`;
  }
  return d + 'Z';
};

