/* ══════════════════════════════════════════════════════════════════════
   WORLD MAP LAYER
   ══════════════════════════════════════════════════════════════════════ */
const useMapGeom = () =>
  useMemo(() => {
    const n = MAP.COLS * MAP.ROWS;
    const land = unpackBits(MAP.land, n);
    const coast = unpackBits(MAP.coast, n);
    const GROUPS = 5;
    let inner = '';
    const coastG: string[] = new Array(GROUPS).fill('');
    for (let r = 0; r < MAP.ROWS; r++) {
      for (let c = 0; c < MAP.COLS; c++) {
        const i = r * MAP.COLS + c;
        if (!land[i]) continue;
        const x = (MAP_X + (c + 0.5) * MAP.P).toFixed(1);
        const y = (MAP_Y + (r + 0.5) * MAP.P).toFixed(1);
        const s = `M${x} ${y}h.01`;
        if (coast[i]) coastG[Math.floor(random(`g${i}`) * GROUPS)] += s;
        else inner += s;
      }
    }
    const outline = MAP.outline
      .replace(/M([\d.]+) ([\d.]+)/g, (_m, a, b) =>
        `M${(parseFloat(a) + MAP_X).toFixed(1)} ${(parseFloat(b) + MAP_Y).toFixed(1)}`
      )
      .replace(/L([\d.]+) ([\d.]+)/g, (_m, a, b) =>
        `L${(parseFloat(a) + MAP_X).toFixed(1)} ${(parseFloat(b) + MAP_Y).toFixed(1)}`
      );
    return { inner, coastG, outline, all: inner + coastG.join('') };
  }, []);

const WorldMap: React.FC<{ f: number; bloom?: boolean }> = ({ f, bloom }) => {
  const g = useMapGeom();
  const sweepX = ((f % 600) / 600) * (W + 520) - 260;

  return (
    <svg width={W} height={H} viewBox={`0 0 ${W} ${H}`} style={{ position: 'absolute' }}>
      <defs>
        <linearGradient
          id="sweepG"
          gradientUnits="userSpaceOnUse"
          x1={sweepX - 250}
          y1={0}
          x2={sweepX + 200}
          y2={0}
        >
          <stop offset="0%" stopColor="#ff5a4a" stopOpacity="0" />
          <stop offset="46%" stopColor="#ff7a5a" stopOpacity="0.5" />
          <stop offset="61%" stopColor="#ffd0ae" stopOpacity="1" />
          <stop offset="74%" stopColor="#ff5a4a" stopOpacity="0.28" />
          <stop offset="100%" stopColor="#ff5a4a" stopOpacity="0" />
        </linearGradient>
        <linearGradient id="mapFade" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stopColor="#fff" stopOpacity="0" />
          <stop offset="9%" stopColor="#fff" stopOpacity="1" />
          <stop offset="88%" stopColor="#fff" stopOpacity="1" />
          <stop offset="100%" stopColor="#fff" stopOpacity="0" />
        </linearGradient>
        <mask id="mapMask">
          <rect x="0" y={MAP_Y - 12} width={W} height={MAP.MH + 24} fill="url(#mapFade)" />
        </mask>
      </defs>

      {bloom ? (
        <g mask="url(#mapMask)">
          <path d={g.outline} fill="none" stroke={C.outline} strokeWidth={1.1} opacity={0.5} />
          <path d={g.all} stroke={C.coastDot} strokeWidth={3.4} strokeLinecap="round" fill="none" opacity={0.5} />
          <g style={{ mixBlendMode: 'screen' }}>
            <path d={g.all} stroke="url(#sweepG)" strokeWidth={4.4} strokeLinecap="round" fill="none" />
          </g>
        </g>
      ) : (
      <g mask="url(#mapMask)">
        {/* graticule */}
        <g stroke="#ff2a3a" strokeWidth={0.8} opacity={0.075}>
          {Array.from({ length: 9 }, (_, i) => {
            const y = MAP_Y + ((MAP.LAT_MAX - (60 - i * 15)) / DEG_PER_PX);
            return <line key={`h${i}`} x1={0} y1={y} x2={W} y2={y} />;
          })}
          {Array.from({ length: 13 }, (_, i) => {
            const x = MAP_X + ((i * 30) / DEG_PER_PX);
            return <line key={`v${i}`} x1={x} y1={MAP_Y} x2={x} y2={MAP_Y + MAP.MH} />;
          })}
        </g>

        {/* coastline outline */}
        <path d={g.outline} fill="none" stroke={C.outline} strokeWidth={4.5} opacity={0.09} />
        <path d={g.outline} fill="none" stroke={C.outline} strokeWidth={1.1} opacity={0.5} />

        {/* land dots */}
        <path d={g.inner} stroke={C.landDot} strokeWidth={6.4} strokeLinecap="round" fill="none" opacity={0.16} />
        <path d={g.inner} stroke={C.landDot} strokeWidth={3.4} strokeLinecap="round" fill="none" opacity={1} />
        {g.coastG.map((d, i) => {
          const ph = (f / DUR) * (2 + i) * Math.PI * 2 + i * 1.7;
          const o = 0.72 + 0.26 * Math.sin(ph);
          return (
            <path
              key={i}
              d={d}
              stroke={C.coastDot}
              strokeWidth={3.8}
              strokeLinecap="round"
              fill="none"
              opacity={o}
            />
          );
        })}
        {/* radar sweep lighting the dots */}
        <g style={{ mixBlendMode: 'screen' }}>
          <path d={g.all} stroke="url(#sweepG)" strokeWidth={4.4} strokeLinecap="round" fill="none" />
        </g>
        <rect x={sweepX - 1.2} y={MAP_Y} width={2.4} height={MAP.MH} fill="#ffd9c0" opacity={0.09} />
      </g>
      )}
    </svg>
  );
};

/* ══════════════════════════════════════════════════════════════════════
   ATTACK ARCS + NODES
   ══════════════════════════════════════════════════════════════════════ */
type Arc = {
  a: [number, number];
  b: [number, number];
  c: [number, number];
  len: number;
  T: number;
  off: number;
  ti: number;
};

const useArcs = () =>
  useMemo<Arc[]>(
    () =>
      ROUTES.map(([from, to, T, off]) => {
        const fi = NI(from), tiIdx = NI(to);
        const a = geo(NODES[fi].lon, NODES[fi].lat);
        const b = geo(NODES[tiIdx].lon, NODES[tiIdx].lat);
        const d = Math.hypot(b[0] - a[0], b[1] - a[1]);
        const c: [number, number] = [(a[0] + b[0]) / 2, (a[1] + b[1]) / 2 - d * 0.46 - 26];
        let len = 0;
        let px = a[0], py = a[1];
        for (let i = 1; i <= 40; i++) {
          const t = i / 40, u = 1 - t;
          const x = u * u * a[0] + 2 * u * t * c[0] + t * t * b[0];
          const y = u * u * a[1] + 2 * u * t * c[1] + t * t * b[1];
          len += Math.hypot(x - px, y - py);
          px = x; py = y;
        }
        return { a, b, c, len, T, off, ti: tiIdx };
      }),
    []
  );

const bez = (A: Arc, t: number): [number, number] => {
  const u = 1 - t;
  return [
    u * u * A.a[0] + 2 * u * t * A.c[0] + t * t * A.b[0],
    u * u * A.a[1] + 2 * u * t * A.c[1] + t * t * A.b[1],
  ];
};

const Arcs: React.FC<{ f: number }> = ({ f }) => {
  const arcs = useArcs();
  const impacts: { p: [number, number]; k: number }[] = [];

  const paths = arcs.map((A, i) => {
    const u = (((f - A.off) % A.T) + A.T) % A.T / A.T;
    const head = easeOut(seg(u, 0, 0.46));
    const tail = Math.pow(seg(u, 0.2, 0.78), 1.6);
    const vis = head - tail;
    if (vis <= 0.001) return null;
    const dash = `${(vis * A.len).toFixed(1)} ${(A.len * 1.2).toFixed(1)}`;
    const offset = -(tail * A.len);
    const fade = 1 - Math.pow(seg(u, 0.55, 0.9), 2);
    const hp = bez(A, head);
    const showHead = u < 0.5 && head > 0.02 && head < 0.995;
    const d = `M${A.a[0].toFixed(1)} ${A.a[1].toFixed(1)}Q${A.c[0].toFixed(1)} ${A.c[1].toFixed(1)} ${A.b[0].toFixed(1)} ${A.b[1].toFixed(1)}`;

    const ik = seg(u, 0.46, 0.72);
    if (ik > 0 && ik < 1) impacts.push({ p: A.b, k: ik });

    return (
      <g key={i} opacity={fade}>
        <path d={d} fill="none" stroke="#ff4a2e" strokeWidth={9} opacity={0.13} strokeDasharray={dash} strokeDashoffset={offset} strokeLinecap="round" />
        <path d={d} fill="none" stroke="#ff6a3a" strokeWidth={3.4} opacity={0.6} strokeDasharray={dash} strokeDashoffset={offset} strokeLinecap="round" />
        <path d={d} fill="none" stroke="#ffd8b8" strokeWidth={1.35} opacity={0.95} strokeDasharray={dash} strokeDashoffset={offset} strokeLinecap="round" />
        {showHead && (
          <>
            <circle cx={hp[0]} cy={hp[1]} r={9} fill="#ff5a2e" opacity={0.22} />
            <circle cx={hp[0]} cy={hp[1]} r={3.6} fill="#ffe6cf" />
          </>
        )}
      </g>
    );
  });

  return (
    <svg width={W} height={H} viewBox={`0 0 ${W} ${H}`} style={{ position: 'absolute' }}>
      {paths}
      {impacts.map((im, i) => (
        <g key={`im${i}`}>
          <circle
            cx={im.p[0]}
            cy={im.p[1]}
            r={6 + im.k * 34}
            fill="none"
            stroke="#ff5a3a"
            strokeWidth={2.4 * (1 - im.k)}
            opacity={0.85 * (1 - im.k)}
          />
          <circle
            cx={im.p[0]}
            cy={im.p[1]}
            r={6 + im.k * 19}
            fill="none"
            stroke="#ffd9c0"
            strokeWidth={1.4 * (1 - im.k)}
            opacity={0.6 * (1 - im.k)}
          />
        </g>
      ))}
      {/* node markers */}
      {NODES.map((nd, i) => {
        const p = geo(nd.lon, nd.lat);
        const ph = (f / DUR) * Math.PI * 2 * (3 + (i % 4)) + i * 0.9;
        const pulse = 0.5 + 0.5 * Math.sin(ph);
        return (
          <g key={nd.n}>
            <circle cx={p[0]} cy={p[1]} r={10 + pulse * 5} fill="#ff2a3a" opacity={0.07 + pulse * 0.06} />
            <circle cx={p[0]} cy={p[1]} r={4.4} fill="none" stroke="#ff6a5a" strokeWidth={1.1} opacity={0.6} />
            <circle cx={p[0]} cy={p[1]} r={1.9} fill="#ffe0d2" opacity={0.9} />
          </g>
        );
      })}
    </svg>
  );
};

/* ══════════════════════════════════════════════════════════════════════
   TERMINAL LOG (left column)
   ══════════════════════════════════════════════════════════════════════ */
const LOG_N = 60;
const LH = 27;
const FS = 17;
const COL_W = 600;
const CW = 10.2; // JetBrains Mono advance at 17px
const LOG_X = 58;
const LOG_TOP = 186;
const LOG_H = 756;
const MASK_CSS = 'linear-gradient(to bottom, transparent 0, #000 38px, #000 690px, transparent 756px)';
const TXT_SHADOW = '0 0 12px rgba(5,0,3,0.98), 0 0 4px rgba(5,0,3,1), 0 1px 2px rgba(5,0,3,1)';

type LogLine = { t: string; tag: string; who: string; ev: string; st: string; crit: boolean };

const EVENTS: [string, string, string, boolean][] = [
  ['IDS', 'PORT-SCAN :{p}', 'BLOCKED', false],
  ['AUTH', 'BRUTE-FORCE x{n}', 'LOCKED', false],
  ['WAF', 'SQL-INJECTION', 'BLOCKED', true],
  ['WAF', 'XSS-PAYLOAD', 'SANITIZED', false],
  ['EDR', 'RANSOM-SIGNATURE', 'QUARANTINE', true],
  ['NET', 'DDOS {g} Gbps', 'MITIGATED', true],
  ['DNS', 'TUNNEL-EXFIL', 'SEVERED', true],
  ['API', 'TOKEN-REPLAY', 'REVOKED', false],
  ['MAIL', 'PHISH-CAMPAIGN', 'DROPPED', false],
  ['KEY', 'CERT-SPOOF', 'REJECTED', false],
  ['EDR', 'PRIV-ESCALATION', 'CONTAINED', true],
  ['NET', 'BOTNET-BEACON', 'SINKHOLED', false],
  ['IDS', 'ARP-POISON', 'BLOCKED', false],
  ['WAF', 'PATH-TRAVERSAL', 'BLOCKED', false],
  ['EDR', 'MEM-INJECTION', 'QUARANTINE', true],
];

const useLog = () =>
  useMemo<LogLine[]>(() => {
    const out: LogLine[] = [];
    for (let i = 0; i < LOG_N; i++) {
      const e = EVENTS[Math.floor(random(`e${i}`) * EVENTS.length)];
      const octA = [192, 198, 203][Math.floor(random(`a${i}`) * 3)];
      const octB = octA === 192 ? 0 : octA === 198 ? 51 : 0;
      const octC = octA === 192 ? 2 : octA === 198 ? 100 : 113;
      const ip = `${octA}.${octB}.${octC}.${Math.floor(random(`d${i}`) * 254) + 1}`;
      const secs = 44_460 + i * 7 + Math.floor(random(`s${i}`) * 5);
      const t = `${pad0((secs / 3600) % 24)}:${pad0((secs / 60) % 60)}:${pad0(secs % 60)}`;
      const ev = e[1]
        .replace('{p}', String([22, 445, 3389, 8080, 23][Math.floor(random(`p${i}`) * 5)]))
        .replace('{n}', String(Math.floor(random(`n${i}`) * 900) + 100))
        .replace('{g}', (random(`g${i}`) * 700 + 90).toFixed(0));
      out.push({ t, tag: e[0], who: ip, ev, st: e[2], crit: e[3] });
    }
    return out;
  }, []);

const LogColumn: React.FC<{ f: number }> = ({ f }) => {
  const log = useLog();
  const SPEED = (LH * 20) / DUR; // 20 lines per loop → seam-safe
  const scroll = f * SPEED;
  const first = Math.floor(scroll / LH);
  const yOff = -(scroll % LH);
  const rows = Math.ceil(LOG_H / LH) + 2;

  return (
    <div
      style={{
        position: 'absolute',
        left: LOG_X,
        top: LOG_TOP,
        width: COL_W,
        height: LOG_H,
        overflow: 'hidden',
        fontFamily: 'MxMono',
        fontSize: FS,
        lineHeight: `${LH}px`,
        whiteSpace: 'pre',
        textShadow: TXT_SHADOW,
        maskImage: MASK_CSS,
        WebkitMaskImage: MASK_CSS,
      }}
    >
      {Array.from({ length: rows }, (_, k) => {
        const idx = ((first + k) % LOG_N + LOG_N) % LOG_N;
        const L = log[idx];
        const y = k * LH + yOff;
        const age = clamp01((f - (first + k) * (LH / SPEED)) / 26);
        const fresh = 1 - age;
        return (
          <div key={k} style={{ position: 'absolute', top: y, left: 0, width: COL_W, height: LH }}>
            {L.crit && (
              <div
                style={{
                  position: 'absolute',
                  left: -10,
                  top: 1,
                  width: COL_W + 4,
                  height: LH - 3,
                  background: `linear-gradient(90deg, rgba(255,40,52,${(0.16 + fresh * 0.16).toFixed(3)}) 0%, rgba(255,40,52,${(0.13 + fresh * 0.14).toFixed(3)}) 74%, rgba(255,40,52,0) 100%)`,
                  borderLeft: '2px solid #ff3644',
                }}
              />
            )}
            <div style={{ position: 'relative' }}>
              <span style={{ color: C.dim }}>{L.t} </span>
              <span style={{ color: C.amber, fontWeight: 700 }}>{pad(L.tag, 5)}</span>
              <span style={{ color: C.txt }}>{pad(L.who, 16)}</span>
              <span style={{ color: L.crit ? '#ff5a63' : '#d8636b' }}>{pad(L.ev, 18)}</span>
              <span style={{ color: L.crit ? C.white : '#c88f8c', fontWeight: 700 }}>{L.st}</span>
            </div>
          </div>
        );
      })}
    </div>
  );
};

/* ══════════════════════════════════════════════════════════════════════
   HEX DUMP (right column)
   ══════════════════════════════════════════════════════════════════════ */
const HEX_N = 40;
const HX = 1262;

const useHex = () =>
  useMemo(() => {
    const rows: { addr: string; bytes: number[]; sig: [number, number] | null }[] = [];
    for (let i = 0; i < HEX_N; i++) {
      const bytes = Array.from({ length: 16 }, (_, j) => Math.floor(random(`h${i}_${j}`) * 256));
      const hasSig = random(`sg${i}`) > 0.7;
      const s0 = Math.floor(random(`ss${i}`) * 5);
      const s = random(`sh${i}`) > 0.5 ? s0 : s0 + 8;
      rows.push({
        addr: `0x${hex(0x004a20 + i * 16, 6)}`,
        bytes,
        sig: hasSig ? [s, s + 4] : null,
      });
    }
    return rows;
  }, []);

const HexColumn: React.FC<{ f: number }> = ({ f }) => {
  const rows = useHex();
  const STEP = 30; // one new line every 0.5 s → 40 steps per loop
  const steps = Math.floor(f / STEP);
  const sub = (f % STEP) / STEP;
  const yOff = -smooth(seg(sub, 0, 0.28)) * LH;
  const first = steps;
  const n = Math.ceil(LOG_H / LH) + 2;

  return (
    <div
      style={{
        position: 'absolute',
        left: HX,
        top: LOG_TOP,
        width: COL_W,
        height: LOG_H,
        overflow: 'hidden',
        fontFamily: 'MxMono',
        fontSize: FS,
        lineHeight: `${LH}px`,
        whiteSpace: 'pre',
        textShadow: TXT_SHADOW,
        maskImage: MASK_CSS,
        WebkitMaskImage: MASK_CSS,
      }}
    >
      {Array.from({ length: n }, (_, k) => {
        const idx = ((first + k) % HEX_N + HEX_N) % HEX_N;
        const R = rows[idx];
        const isNew = k === n - 2;
        return (
          <div key={k} style={{ position: 'absolute', top: k * LH + yOff, left: 0, width: COL_W }}>
            {R.sig && (
              <div
                style={{
                  position: 'absolute',
                  left: (9 + R.sig[0] * 3 + (R.sig[0] >= 8 ? 1 : 0)) * CW - 5,
                  top: 3,
                  width: 11 * CW + 10,
                  height: LH - 6,
                  background: 'rgba(255,120,50,0.18)',
                  border: '1px solid rgba(255,150,80,0.42)',
                }}
              />
            )}
            <div style={{ position: 'relative', opacity: isNew ? 0.45 + 0.55 * smooth(sub * 2.4) : 1 }}>
              <span style={{ color: C.dim }}>{R.addr} </span>
              {R.bytes.map((b, j) => {
                const inSig = R.sig && j >= R.sig[0] && j < R.sig[1];
                return (
                  <span key={j} style={{ color: inSig ? '#ffcf9a' : '#d8535f', fontWeight: inSig ? 700 : 400 }}>
                    {hex(b)}{j === 7 ? '  ' : ' '}
                  </span>
                );
              })}
            </div>
          </div>
        );
      })}
    </div>
  );
};

/* ══════════════════════════════════════════════════════════════════════
   HERO — warning triangle
   ══════════════════════════════════════════════════════════════════════ */
const TRI = roundPoly(
  [
    [0, -152],
    [176, 150],
    [-176, 150],
  ],
  30
);
const TRI_IN = roundPoly(
  [
    [0, -96],
    [122, 112],
    [-122, 112],
  ],
  22
);

const beat = (x: number) => {
  const t = clamp01(x);
  return Math.pow(Math.sin(Math.PI * t), 2.2);
};

const Hero: React.FC<{ f: number; glitch: number }> = ({ f, glitch }) => {
  const hbT = (f % 120) / 120; // 10 heartbeats per loop
  const hb = beat(hbT / 0.2) + 0.55 * beat((hbT - 0.26) / 0.2);
  const breathe = 0.5 + 0.5 * Math.sin((f / DUR) * Math.PI * 2 * 5);
  const glow = 0.55 + 0.45 * hb + 0.1 * breathe;
  const scale = 1 + hb * 0.012;
  const cx = 960, cy = 404;

  const ringK = (f % 120) / 120;

  const body = (dx: number, col: string, op: number) => (
    <g transform={`translate(${cx + dx} ${cy}) scale(${scale})`} opacity={op}>
      <path d={TRI} fill="none" stroke={col} strokeWidth={46} opacity={0.05 * glow} strokeLinejoin="round" />
      <path d={TRI} fill="none" stroke={col} strokeWidth={27} opacity={0.13 * glow} strokeLinejoin="round" />
      <path d={TRI} fill="none" stroke={col} strokeWidth={15.5} opacity={0.5 * glow} strokeLinejoin="round" />
      <path d={TRI} fill="none" stroke="#ff5f5f" strokeWidth={8.5} opacity={0.95} strokeLinejoin="round" />
      <path d={TRI} fill="none" stroke={C.core} strokeWidth={2.6} opacity={0.55 + 0.4 * hb} strokeLinejoin="round" />
      <g>
        <rect x={-12} y={-62} width={24} height={104} rx={12} fill={col} opacity={0.55 * glow} />
        <rect x={-8.5} y={-58} width={17} height={96} rx={8.5} fill="#ff6a6a" />
        <rect x={-3.4} y={-54} width={6.8} height={88} rx={3.4} fill={C.core} opacity={0.6 + 0.35 * hb} />
        <circle cx={0} cy={74} r={16} fill={col} opacity={0.5 * glow} />
        <circle cx={0} cy={74} r={11} fill="#ff6a6a" />
        <circle cx={0} cy={74} r={4.4} fill={C.core} opacity={0.6 + 0.35 * hb} />
      </g>
    </g>
  );

  return (
    <svg width={W} height={H} viewBox={`0 0 ${W} ${H}`} style={{ position: 'absolute' }}>
      {/* alert shock rings */}
      <g opacity={0.55}>
        {[0, 1, 2].map((i) => {
          const k = (ringK + i / 3) % 1;
          return (
            <path
              key={i}
              d={TRI}
              transform={`translate(${cx} ${cy}) scale(${1.05 + k * 0.6})`}
              fill="none"
              stroke="#ff3a44"
              strokeWidth={2.2}
              opacity={0.5 * (1 - k) * (1 - k)}
              strokeLinejoin="round"
            />
          );
        })}
      </g>
      {/* inner faint plate */}
      <path
        d={TRI_IN}
        transform={`translate(${cx} ${cy}) scale(${scale})`}
        fill="#ff2233"
        opacity={0.05 + 0.045 * hb}
      />
      {glitch > 0 && (
        <g style={{ mixBlendMode: 'screen' }}>
          {body(-13 * glitch, '#ff0022', 0.75)}
          {body(11 * glitch, '#00e0ff', 0.42)}
        </g>
      )}
      {body(0, C.red, 1)}
    </svg>
  );
};

