/* ══════════════════════════════════════════════════════════════════════
   FX
   ══════════════════════════════════════════════════════════════════════ */
const GLITCHES: [number, number][] = [
  [96, 14],
  [318, 10],
  [522, 16],
  [720, 9],
  [906, 13],
  [1104, 11],
];
const glitchAt = (f: number) => {
  let g = 0;
  for (const [s, d] of GLITCHES) {
    if (f >= s && f < s + d) {
      const u = (f - s) / d;
      g = Math.max(g, (1 - u) * (0.55 + 0.45 * random(`gl${f}`)));
    }
  }
  return g;
};

const Fx: React.FC<{ f: number; glitch: number }> = ({ f, glitch }) => {
  const bands = glitch > 0 ? Array.from({ length: 6 }, (_, i) => i) : [];
  return (
    <AbsoluteFill style={{ pointerEvents: 'none' }}>
      {/* scanlines */}
      <AbsoluteFill
        style={{
          background: 'repeating-linear-gradient(0deg, rgba(0,0,0,0.34) 0px, rgba(0,0,0,0.34) 1px, transparent 1px, transparent 3px)',
          opacity: 0.55,
        }}
      />
      {/* rolling bright bar */}
      <div
        style={{
          position: 'absolute',
          left: 0,
          top: ((f * 2.2) % (H + 300)) - 150,
          width: W,
          height: 150,
          background: 'linear-gradient(180deg, rgba(255,60,70,0) 0%, rgba(255,90,80,0.055) 50%, rgba(255,60,70,0) 100%)',
          mixBlendMode: 'screen',
        }}
      />
      {/* glitch tear bands */}
      {bands.map((i) => {
        const y = random(`by${f}_${i}`) * H;
        const h = 4 + random(`bh${f}_${i}`) * 26;
        const dx = (random(`bx${f}_${i}`) - 0.5) * 90 * glitch;
        return (
          <div
            key={i}
            style={{
              position: 'absolute',
              left: dx,
              top: y,
              width: W,
              height: h,
              background: i % 2 ? 'rgba(255,60,72,0.16)' : 'rgba(180,230,255,0.09)',
              mixBlendMode: 'screen',
            }}
          />
        );
      })}
      {/* grain */}
      <svg width={W} height={H} style={{ position: 'absolute', opacity: 0.085, mixBlendMode: 'overlay' }}>
        <filter id="gr" x="0" y="0" width="100%" height="100%">
          <feTurbulence type="fractalNoise" baseFrequency="0.9" numOctaves={1} seed={f % 8} stitchTiles="stitch" />
        </filter>
        <rect width={W} height={H} filter="url(#gr)" />
      </svg>
      {/* vignette */}
      <AbsoluteFill
        style={{
          background:
            'radial-gradient(120% 88% at 50% 46%, rgba(0,0,0,0) 38%, rgba(4,0,3,0.62) 78%, rgba(2,0,2,0.94) 100%)',
        }}
      />
      {/* flash on glitch */}
      {glitch > 0 && (
        <AbsoluteFill style={{ background: `rgba(255,70,70,${0.05 * glitch})`, mixBlendMode: 'screen' }} />
      )}
    </AbsoluteFill>
  );
};

