export const Motion: React.FC = () => {
  useEmbeddedFonts();
  const frame = useCurrentFrame();
  const f = ((frame % DUR) + DUR) % DUR;
  const glitch = glitchAt(f);

  return (
    <AbsoluteFill style={{ backgroundColor: C.void, overflow: 'hidden' }}>
      <Scene f={f} glitch={glitch} />
      <AbsoluteFill
        style={{
          filter: 'blur(26px)',
          mixBlendMode: 'screen',
          opacity: 0.34,
          pointerEvents: 'none',
        }}
      >
        <Scene f={f} glitch={glitch} bloom />
      </AbsoluteFill>
      <Fx f={f} glitch={glitch} />
    </AbsoluteFill>
  );
};
